public class Solution {
    public static int compress(int[] arr) {
        // CONTRACT: sum of elements, but each run of equal adjacent
        // elements counts ONCE. {2,2,5,5,5,1} -> 2 + 5 + 1 = 8.
        int total = 0;
        for (int i = 0; i < arr.length; i++) {
            total += arr[i];
        }
        return total;
    }
}

